163	/**
164	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
165	 *
166	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
167	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
168	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
169	 *   treated as "no scope filter" rather than causing an error.
170	 * - `tags` is a comma-separated string that is split before being forwarded.
171	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
172	 *   are silently ignored (limit → undefined, offset → 0).
173	 * - `limit=0` is treated as unlimited (mapped to undefined); pass a positive integer
174	 *   to enforce a page size.
175	 */
176	export async function handleListKnowledge(
177	  ledgerRoot: string,
178	  params: KnowledgeListParams = {}
179	): Promise<Insight[]> {
180	  const manager = new KnowledgeStoreManager(ledgerRoot);
181	
182	  // Validate scope — unrecognised values fall back to undefined (no filter).
183	  const scopeResult = InsightScope.safeParse(params.scope);
184	  const scope = scopeResult.success ? scopeResult.data : undefined;
185	
186	  const category = params.category ?? undefined;
187	  const repository_name = params.repository_name ?? undefined;
188	
189	  // Split comma-separated tags; ignore empty segments.
190	  const tags =
191	    params.tags && params.tags.trim().length > 0
192	      ? params.tags
193	          .split(',')
194	          .map((t) => t.trim())
195	          .filter((t) => t.length > 0)
196	      : undefined;
197	
198	  // Coerce pagination params.
199	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
200	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
201	
202	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
203	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
204	
