216	/**
217	 * Updates an existing knowledge insight identified by its numeric ID.
218	 *
219	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
220	 * for non-integer, zero, or floating-point strings). Validates the request body
221	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
222	 * type mismatches). Extracts `scope` and `repository_name` discriminator fields to
223	 * scope the update to the correct store.
224	 *
225	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
226	 * cleared (removed) on the stored insight.
227	 *
228	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
229	 *
230	 * @param ledgerRoot  Absolute path to the central ledger root.
231	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
232	 * @param body        Parsed request body (any shape — validated here).
233	 * @returns The updated Insight.
234	 */
235	export async function handleUpdateKnowledge(
236	  ledgerRoot: string,
237	  rawId: string,
238	  body: unknown
239	): Promise<Insight> {
240	  const id = parseKnowledgeId(rawId);
241	
242	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
243	  if (!parseResult.success) {
244	    validationError('Invalid knowledge update body.', parseResult.error.issues);
245	  }
246	
247	  const { scope, repository_name, superseded_by, ...rest } = parseResult.data;
248	
249	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
250	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
251	    ...rest,
252	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
253	  };
254	
255	  const manager = new KnowledgeStoreManager(ledgerRoot);
256	
257	  try {
258	    return await manager.updateInsight(id, updates, { scope, repository_name });
259	  } catch (err) {
260	    const msg = err instanceof Error ? err.message : String(err);
261	    if (msg.includes('not found')) {
262	      throw new ApiError('NOT_FOUND', 'Insight not found.');
263	    }
264	    throw err;
265	  }
266	}
