342	/**
343	 * Promotes a repository-scoped insight to global scope using the atomic
344	 * KnowledgeStoreManager.moveInsight() method.
345	 *
346	 * The returned insight is the newly created global-scoped copy — it has a
347	 * **different numeric ID** than the original (assigned by the global store's
348	 * `next_id` counter). The frontend must match by pre-promote ID, not the new ID.
349	 *
350	 * **Defence-in-depth note:** `repository_name` is accepted as a raw query-parameter
351	 * string and is NOT validated against `PROJECT_SLUG_REGEX` at this handler level.
352	 * The storage layer's `_validateSlug()` enforces the regex before constructing any
353	 * file path, making path-traversal attacks impossible in practice. However, because
354	 * `_validateSlug()` throws a generic `Error` (not an `ApiError`), a malformed slug
355	 * will propagate to the server's unhandled-error branch and return HTTP 500 rather
356	 * than a semantically correct HTTP 400 `VALIDATION_ERROR`. Contrast with
357	 * `handleMoveKnowledge` and `handleUpdateKnowledge`, where `repository_name` is
358	 * validated via Zod schema (`z.string().regex(PROJECT_SLUG_REGEX)`) before reaching
359	 * the storage layer. A future hardening pass should add an explicit regex guard here
360	 * (mirroring the Zod pattern) to return a proper 400 and remove reliance on the
361	 * storage layer as the sole validation point for this field.
362	 *
363	 * @param ledgerRoot      Absolute path to the central ledger root.
364	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
365	 * @param scope           Source scope — must be "repository" (global insights cannot be promoted).
366	 * @param repository_name Required when scope is "repository"; the source repository name.
367	 * @returns The newly created global Insight.
368	 * @throws ApiError VALIDATION_ERROR if scope is not "repository", or insight is already global.
369	 * @throws ApiError NOT_FOUND if no matching insight exists in the specified scope.
370	 */
371	export async function handlePromoteKnowledge(
372	  ledgerRoot: string,
373	  rawId: string,
374	  scope: string | undefined,
375	  repository_name?: string
376	): Promise<Insight> {
377	  const id = parseKnowledgeId(rawId);
378	
379	  // Validate scope — must be 'repository' (global insights are already global).
380	  const scopeResult = InsightScope.safeParse(scope);
381	  if (!scopeResult.success) {
382	    validationError('scope query parameter is required and must be "global" or "repository".');
383	  }
384	  const validatedScope = scopeResult.data;
385	
386	  if (validatedScope === 'global') {
387	    validationError('Insight is already global and cannot be promoted.');
388	  }
389	
390	  // repository_name is required when scope === 'repository'.
391	  if (!repository_name) {
392	    validationError('repository_name query parameter is required when scope is "repository".');
393	  }
394	
395	  const manager = new KnowledgeStoreManager(ledgerRoot);
396	
397	  try {
398	    return await manager.moveInsight(
399	      id,
400	      { scope: validatedScope, repository_name },
401	      'global'
402	    );
403	  } catch (err) {
404	    const msg = err instanceof Error ? err.message : String(err);
405	    if (msg.toLowerCase().includes('not found')) {
406	      throw new ApiError('NOT_FOUND', 'Insight not found.');
407	    }
408	    throw err;
409	  }
410	}
