413	// POST /api/knowledge/:id/move
414	// ---------------------------------------------------------------------------
415	
416	/**
417	 * Moves an insight from one scope/repository to a different repository using the
418	 * atomic KnowledgeStoreManager.moveInsight() method.

417	 * Moves an insight from one scope/repository to a different repository using the
418	 * atomic KnowledgeStoreManager.moveInsight() method.
419	 *
420	 * Supports two move variants:
421	 * - global → repository: moves the global insight into a named repository store
422	 * - repository → repository: moves a repository insight to a different repository
423	 *
424	 * The returned insight is the newly created copy — it has a **different numeric
425	 * ID** (assigned by the target store's `next_id` counter).
426	 *
427	 * @param ledgerRoot  Absolute path to the central ledger root.
428	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
429	 * @param body        Parsed request body (validated against KnowledgeMoveBodySchema).
430	 * @returns The newly created Insight in the target repository store.
431	 * @throws ApiError VALIDATION_ERROR when source and destination are identical, body is invalid,
432	 *   or the destination name fails PROJECT_SLUG_REGEX.
433	 * @throws ApiError NOT_FOUND when no matching insight exists in the source scope.
434	 */
435	export async function handleMoveKnowledge(
436	  ledgerRoot: string,
437	  rawId: string,
438	  body: unknown
439	): Promise<Insight> {
440	  const id = parseKnowledgeId(rawId);
441	
442	  const parseResult = KnowledgeMoveBodySchema.safeParse(body);
443	  if (!parseResult.success) {
444	    validationError('Invalid knowledge move body.', parseResult.error.issues);
445	  }
446	
447	  const { source_scope, source_repository_name, repository_name } = parseResult.data;
448	
449	  // Require source_repository_name when source_scope is 'repository'.
450	  if (source_scope === 'repository' && !source_repository_name) {
451	    validationError('source_repository_name is required when source_scope is "repository".');
452	  }
453	
454	  // Validate that source and destination are not identical.
455	  // global → repository always changes scope, so no identity check is needed for that case.
456	  if (source_scope === 'repository' && source_repository_name === repository_name) {
457	    validationError('Source and destination repository are identical; nothing to move.');
458	  }
459	
460	  const manager = new KnowledgeStoreManager(ledgerRoot);
461	
462	  try {
463	    return await manager.moveInsight(
464	      id,
465	      { scope: source_scope, repository_name: source_repository_name },
466	      'repository',
467	      repository_name
468	    );
469	  } catch (err) {
470	    const msg = err instanceof Error ? err.message : String(err);
471	    if (msg.toLowerCase().includes('not found')) {
472	      throw new ApiError('NOT_FOUND', 'Insight not found.');
473	    }
474	    throw err;
475	  }
476	}

